class Solution {
public:
    int trap(vector<int>& height) {
        stack<int> stk;
        int res = 0;
        for (int i = 0; i < height.size(); i ++ ) {
            int last = 0;
            while (stk.size() && height[stk.top()] <= height[i]) { // 维护单调栈
                res += (height[stk.top()] - last) * (i - stk.top() - 1);  // 计算当前高度层的雨水面积
                last = height[stk.top()];
                stk.pop();                                       // 出栈
            }

            if (stk.size()) res += (i - stk.top() - 1) * (height[i] - last);  // 处理栈顶剩余部分
            stk.push(i);                                         // 入栈
        }

        return res;
    }
};
